-- 025: run speeds a hundred times too high.
--
-- 193 NPCs of the dump (Innothule, Grobb, the Plane of Hate, Cazic-Thule's Temple...) had run speeds such as 250
-- where every other NPC has 1.25. The zone turns the speed into a signed byte for the client (walk: speed x 4,
-- run: speed / 0.64 x 7), so theirs overflowed: a negative velocity and steps of 30 to 60 units. They looked fine as
-- long as they stood still; once Innothule's NPCs roamed (023) they jumped back and forth.
-- Each takes the run speed of the Quarm NPC of the same zone and name, or its own divided by 200 when Quarm has
-- none (250 -> 1.25). Both NPC tables. The old values are kept in npc_runspeed_before_025. Idempotent.

CREATE TABLE IF NOT EXISTS npc_runspeed_before_025 (id INT NOT NULL PRIMARY KEY, runspeed FLOAT NOT NULL);

